public partial class DesktopApplication {
    System.Windows.Controls.WrapPanel groupLiveRow;System.Windows.Controls.Button groupGraphs;
    System.Windows.Window groupDiagnosticWindow;System.Windows.Controls.TabControl groupDiagnosticTabs;
    readonly Queue<GroupTelemetryProjection> groupSamples=new Queue<GroupTelemetryProjection>();
    readonly Queue<string> groupTelemetryEvents=new Queue<string>();GroupTelemetryProjection groupTelemetry=new GroupTelemetryProjection();
    string groupTelemetryContext="",groupTelemetryTitle="",lastGroupTelemetryState="";DateTime nextGroupTelemetry;bool graphsPaused;
    void BuildGroupTelemetrySurface(System.Windows.Controls.StackPanel actions){
        groupGraphs=new System.Windows.Controls.Button{Content="▥ Diagnostics Graph",Padding=new System.Windows.Thickness(9,6,9,6),Margin=new System.Windows.Thickness(6,0,0,0),Visibility=System.Windows.Visibility.Collapsed};groupGraphs.Click+=(s,e)=>OpenContextDiagnostics(DiagnosticSection.GroupCalls,model.SelectedGroup==null?"":model.SelectedGroup.Id);actions.Children.Insert(Math.Max(0,actions.Children.IndexOf(Find<System.Windows.Controls.Button>("GroupOverflow"))),groupGraphs);
        groupLiveRow=new System.Windows.Controls.WrapPanel{Margin=new System.Windows.Thickness(0,12,0,0),Visibility=System.Windows.Visibility.Collapsed};var header=Find<System.Windows.Controls.Border>("VoiceCard").Parent as System.Windows.Controls.StackPanel;header.Children.Insert(1,groupLiveRow);
        groupCreateVoice.Content="Voice Room";groupCreateScreen.Content="Screen Room";
        window.Closed+=(s,e)=>{if(groupDiagnosticWindow!=null)groupDiagnosticWindow.Close();groupSamples.Clear();};
    }
    void RefreshGroupTelemetry(){
        if(groupGraphs==null)return;bool selected=model.Groups&&model.SelectedGroup!=null;groupGraphs.Visibility=selected?System.Windows.Visibility.Visible:System.Windows.Visibility.Collapsed;
        string id=selected?model.SelectedGroup.Id:"";ServerGroupRoster roster=null;if(selected)serverGroupRosters.TryGetValue(id,out roster);string serverId=roster==null?"":roster.GroupId;
        string context=profileSessionGeneration+":"+discoverySessionGeneration+":"+id+":"+serverId;
        if(context!=groupTelemetryContext){groupTelemetryContext=context;groupSamples.Clear();groupTelemetryEvents.Clear();groupTelemetry=new GroupTelemetryProjection();lastGroupTelemetryState="";nextGroupTelemetry=DateTime.MinValue;}
        if(DateTime.UtcNow<nextGroupTelemetry)return;nextGroupTelemetry=DateTime.UtcNow.AddSeconds(1);groupTelemetryTitle=selected?model.SelectedGroup.Name:"No group selected";
        groupTelemetry=GroupTelemetryProjection.Create(groupVoice==null?"{}":groupVoice.Metrics(serverId),groupScreen==null?new string[0]:groupScreen.Metrics(serverId));
        string state=groupTelemetry.Voice+" / "+groupTelemetry.Screen+" / "+groupTelemetry.Transport;if(state!=lastGroupTelemetryState){lastGroupTelemetryState=state;groupTelemetryEvents.Enqueue(DateTime.UtcNow.ToString("HH:mm:ss")+" UTC · "+state);while(groupTelemetryEvents.Count>64)groupTelemetryEvents.Dequeue();}
        if(!graphsPaused){groupSamples.Enqueue(new GroupTelemetryProjection{CapturedFps=groupTelemetry.CapturedFps,EncodedFps=groupTelemetry.EncodedFps,PresentedFps=groupTelemetry.PresentedFps,UploadMbps=groupTelemetry.UploadMbps,DownloadMbps=groupTelemetry.DownloadMbps});while(groupSamples.Count>120)groupSamples.Dequeue();}
        groupLiveRow.Children.Clear();groupLiveRow.Visibility=selected&&(groupTelemetry.VoiceActive||groupTelemetry.ScreenActive)?System.Windows.Visibility.Visible:System.Windows.Visibility.Collapsed;
        foreach(var label in new[]{groupTelemetry.Voice,groupTelemetry.Screen,"Route: "+groupTelemetry.Transport,"Encoded FPS: "+GroupTelemetryProjection.Metric(groupTelemetry.EncodedFps),"↑ Payload "+GroupTelemetryProjection.Metric(groupTelemetry.UploadMbps)+" Mbps","↓ Payload "+GroupTelemetryProjection.Metric(groupTelemetry.DownloadMbps)+" Mbps"}){
            groupLiveRow.Children.Add(new System.Windows.Controls.Border{CornerRadius=new System.Windows.CornerRadius(7),Background=Brush("#142532"),BorderBrush=Brush("#2A475B"),BorderThickness=new System.Windows.Thickness(1),Margin=new System.Windows.Thickness(0,0,6,6),Padding=new System.Windows.Thickness(9),Child=new System.Windows.Controls.TextBlock{Text=label,FontSize=11,Foreground=Brush("#83CCFC")}});
        }
        UpdateGroupDiagnosticWindow();
    }
    void OpenGroupDiagnostics(){
        if(groupDiagnosticWindow!=null){groupDiagnosticWindow.Activate();return;}
        var w=new System.Windows.Window{Title=groupTelemetryTitle+" — Diagnostics & Graphs",Owner=window,Width=1080,Height=700,MinWidth=540,MinHeight=420,Resources=window.Resources,FontFamily=new System.Windows.Media.FontFamily("Segoe UI"),Background=Brush("#0D1720"),Foreground=System.Windows.Media.Brushes.LightGray,WindowStartupLocation=System.Windows.WindowStartupLocation.CenterOwner};groupDiagnosticWindow=w;
        var root=new System.Windows.Controls.DockPanel{Margin=new System.Windows.Thickness(14)};BuildDiagnosticNavigation(root);var controls=new System.Windows.Controls.WrapPanel{Margin=new System.Windows.Thickness(0,8,0,0)};System.Windows.Controls.DockPanel.SetDock(controls,System.Windows.Controls.Dock.Bottom);root.Children.Add(controls);
        Action<string,Action> action=(label,callback)=>{var b=new System.Windows.Controls.Button{Content=label,Tag=label,Background=Brush("#172A38"),Foreground=Brush("#EDF1F5"),BorderBrush=Brush("#2B4355"),Padding=new System.Windows.Thickness(12,7,12,7),Margin=new System.Windows.Thickness(0,0,8,0)};b.Click+=(s,e)=>callback();controls.Children.Add(b);};
        action("Copy Diagnostics",()=>CopyDiagnosticText(CurrentDiagnosticExport(),diagnosticContext.Section==DiagnosticSection.Connections&&connectionsDeveloperPreview?"Sample connections preview copied (not a real report).":"Diagnostics copied."));action("Export…",()=>{var pick=new Microsoft.Win32.SaveFileDialog{FileName=diagnosticContext.Section==DiagnosticSection.Connections&&connectionsDeveloperPreview?"PeerChat-SAMPLE-connections.txt":"PeerChat-diagnostics.txt",Filter="Text|*.txt"};if(pick.ShowDialog(w)==true)try{System.IO.File.WriteAllText(pick.FileName,CurrentDiagnosticExport(),new System.Text.UTF8Encoding(false));}catch{Notify("Could not export diagnostics.");}});
        action("Pause graphs",()=>{graphsPaused=!graphsPaused;((System.Windows.Controls.Button)controls.Children[2]).Content=graphsPaused?"Resume graphs":"Pause graphs";RefreshDiagnosticLayout();});action("Close",()=>w.Close());
        groupDiagnosticTabs=new System.Windows.Controls.TabControl{Background=Brush("#0D1720"),BorderThickness=new System.Windows.Thickness(0),ItemContainerStyle=diagnosticSecondaryTabs,Template=DiagnosticTabContainer(false),ItemsPanel=DiagnosticTabPanel()};foreach(string tab in new[]{"Overview","Screen Share","Voice","Participants","Events","Export"})groupDiagnosticTabs.Items.Add(new System.Windows.Controls.TabItem{Header=tab});root.Children.Add(groupDiagnosticTabs);w.Content=root;BindConnectionsViewRefresh(w);w.Closed+=(s,e)=>{groupDiagnosticWindow=null;groupDiagnosticTabs=null;graphsPaused=false;diagnosticNavigation=null;diagnosticExamples=null;connectionPreviewExamples=null;connectionPreviewStatePanel=null;connectionPreview=null;diagnosticBanner=null;};diagnosticNavigation.SelectedIndex=(int)diagnosticContext.Section;RefreshDiagnosticLayout();w.Show();
    }
    string GroupDiagnosticExport(){return DiagnosticsPrivacyFilter.Redact("PeerChat group telemetry/v1\nBuild: "+PeerChat.VersionInfo.Display+"\nCaptured UTC: "+DateTime.UtcNow.ToString("o")+"\n"+groupTelemetry.Text+"\nHistory Sync: "+(archiveProgress==null?"Not available":archiveProgress.CurrentActivity+"\n"+archiveProgress.LastResultSummary)+"\nEvents:\n"+String.Join("\n",groupTelemetryEvents));}
    System.Windows.Controls.TextBox GroupDiagnosticText(string text){return new System.Windows.Controls.TextBox{Text=text,FontSize=diagnosticTextSize,IsReadOnly=true,AcceptsReturn=true,TextWrapping=System.Windows.TextWrapping.Wrap,VerticalScrollBarVisibility=System.Windows.Controls.ScrollBarVisibility.Auto,Background=Brush("#111D27"),Foreground=System.Windows.Media.Brushes.LightGray,BorderThickness=new System.Windows.Thickness(0),Padding=new System.Windows.Thickness(14)};}
    System.Windows.Controls.Border GroupDiagnosticCard(string title,string text,string color){var body=new System.Windows.Controls.StackPanel();body.Children.Add(new System.Windows.Controls.Border{Background=Brush(color),Padding=new System.Windows.Thickness(12,8,12,8),Child=new System.Windows.Controls.TextBlock{Text=title,FontSize=14,FontWeight=System.Windows.FontWeights.SemiBold,Foreground=System.Windows.Media.Brushes.White}});body.Children.Add(GroupDiagnosticText(text));return new System.Windows.Controls.Border{Child=body,Width=440,MinHeight=diagnosticCompact?100:160,Margin=new System.Windows.Thickness(4),BorderBrush=Brush("#2B4355"),BorderThickness=new System.Windows.Thickness(1),CornerRadius=new System.Windows.CornerRadius(8)};}
    readonly HashSet<string> diagnosticExpanded=new HashSet<string>();
    System.Windows.Controls.Expander GroupAdvanced(string title,string text){var expander=new System.Windows.Controls.Expander{Header=title,Content=GroupDiagnosticText(text),IsExpanded=diagnosticExpanded.Contains(title),Margin=new System.Windows.Thickness(8),Foreground=Brush("#83CCFC")};expander.Expanded+=(s,e)=>diagnosticExpanded.Add(title);expander.Collapsed+=(s,e)=>diagnosticExpanded.Remove(title);return expander;}
    System.Windows.Controls.ScrollViewer GroupDetailPage(string title,string summary,string details){var body=new System.Windows.Controls.StackPanel();body.Children.Add(GroupDiagnosticCard(title,summary,"#174D79"));body.Children.Add(GroupAdvanced("Advanced "+title+" measurements",details));return new System.Windows.Controls.ScrollViewer{Content=body,VerticalScrollBarVisibility=System.Windows.Controls.ScrollBarVisibility.Auto};}
    System.Windows.Controls.ScrollViewer GroupParticipantPage(){var body=new System.Windows.Controls.StackPanel();body.Children.Add(GroupDiagnosticText("Authenticated route detail · payload counters are per route, not remote playback confirmation."));var lines=groupTelemetry.Participants.Split(new[]{'\n'},StringSplitOptions.RemoveEmptyEntries);if(lines.Length==0)body.Children.Add(GroupDiagnosticText("No active participant routes · N/A"));foreach(var line in lines)body.Children.Add(GroupAdvanced(line.Split(new[]{" · "},StringSplitOptions.None)[0]+" · route details",line));return new System.Windows.Controls.ScrollViewer{Content=body,VerticalScrollBarVisibility=System.Windows.Controls.ScrollBarVisibility.Auto};}
    System.Windows.Controls.StackPanel GroupGraph(string label,Func<GroupTelemetryProjection,double?> select){
        var panel=new System.Windows.Controls.StackPanel();if(!groupSamples.Select(select).Any(v=>v.HasValue)){panel.Children.Add(new System.Windows.Controls.TextBlock{Text=label+" · N/A — no samples",Margin=new System.Windows.Thickness(8),Foreground=Brush("#83CCFC")});return panel;}panel.Children.Add(new System.Windows.Controls.TextBlock{Text=label+" · last 120 samples · N/A gaps omitted",Margin=new System.Windows.Thickness(8),Foreground=Brush("#83CCFC")});var canvas=new System.Windows.Controls.Canvas{Height=110,Margin=new System.Windows.Thickness(8),Background=Brush("#0C1720")};panel.Children.Add(canvas);
        Action draw=()=>{canvas.Children.Clear();var values=groupSamples.Select(select).ToArray();double max=Math.Max(1,values.Where(v=>v.HasValue).Select(v=>v.Value).DefaultIfEmpty(1).Max());System.Windows.Shapes.Polyline line=null;for(int n=0;n<values.Length;n++){if(!values[n].HasValue){line=null;continue;}if(line==null){line=new System.Windows.Shapes.Polyline{Stroke=Brush("#65D8AA"),StrokeThickness=2};canvas.Children.Add(line);}line.Points.Add(new System.Windows.Point(n*Math.Max(1,canvas.ActualWidth)/119,100-90*values[n].Value/max));}};canvas.SizeChanged+=(s,e)=>draw();canvas.Loaded+=(s,e)=>draw();return panel;
    }
    void UpdateGroupDiagnosticWindow(){
        if(groupDiagnosticWindow==null||groupDiagnosticTabs==null||diagnosticContext.Section!=DiagnosticSection.GroupCalls)return;groupDiagnosticWindow.Title=groupTelemetryTitle+" — Diagnostics & Graphs";RefreshDiagnosticFooter();
        var overview=new System.Windows.Controls.StackPanel();var panels=new System.Windows.Controls.WrapPanel();if(groupTelemetry.ScreenActive){var screen=GroupDiagnosticText(groupTelemetry.Screen+"\nCaptured / encoded / presented FPS: "+GroupTelemetryProjection.Metric(groupTelemetry.CapturedFps)+" / "+GroupTelemetryProjection.Metric(groupTelemetry.EncodedFps)+" / "+GroupTelemetryProjection.Metric(groupTelemetry.PresentedFps));panels.Children.Add(GroupDiagnosticCard("Screen Share",screen.Text,"#174D79"));}if(groupTelemetry.VoiceActive){var voice=GroupDiagnosticText(groupTelemetry.Voice+"\n"+groupTelemetry.Health);panels.Children.Add(GroupDiagnosticCard("Voice",voice.Text,"#553786"));}if(!groupTelemetry.VoiceActive&&!groupTelemetry.ScreenActive)panels.Children.Add(GroupDiagnosticText("Idle — no current authenticated media participation.\nUnavailable measurements are N/A, not estimates."));overview.Children.Add(panels);if(groupTelemetry.ScreenActive)overview.Children.Add(GroupAdvanced("Advanced screen-share routes",groupTelemetry.ScreenHealth));if(groupTelemetry.ScreenActive)overview.Children.Add(GroupGraph("Encoded FPS",p=>p.EncodedFps));if(groupTelemetry.ScreenActive||groupTelemetry.VoiceActive){overview.Children.Add(GroupGraph("Payload upload Mbps (aggregate)",p=>p.UploadMbps));overview.Children.Add(GroupGraph("Payload received Mbps (aggregate)",p=>p.DownloadMbps));}
        ((System.Windows.Controls.TabItem)groupDiagnosticTabs.Items[0]).Content=new System.Windows.Controls.ScrollViewer{Content=overview,VerticalScrollBarVisibility=System.Windows.Controls.ScrollBarVisibility.Auto};
        ((System.Windows.Controls.TabItem)groupDiagnosticTabs.Items[1]).Content=GroupDetailPage("Screen Share",groupTelemetry.Screen+"\nCaptured / encoded / presented FPS: "+GroupTelemetryProjection.Metric(groupTelemetry.CapturedFps)+" / "+GroupTelemetryProjection.Metric(groupTelemetry.EncodedFps)+" / "+GroupTelemetryProjection.Metric(groupTelemetry.PresentedFps),groupTelemetry.ScreenHealth+"\n"+groupTelemetry.Participants+"\nRTT / packet loss / end-to-end delay: N/A");
        ((System.Windows.Controls.TabItem)groupDiagnosticTabs.Items[2]).Content=GroupDetailPage("Voice",groupTelemetry.Voice+"\n"+groupTelemetry.Health,groupTelemetry.Participants);
        ((System.Windows.Controls.TabItem)groupDiagnosticTabs.Items[3]).Content=GroupParticipantPage();
        ((System.Windows.Controls.TabItem)groupDiagnosticTabs.Items[4]).Content=GroupDiagnosticText(String.Join("\n",groupTelemetryEvents));
        ((System.Windows.Controls.TabItem)groupDiagnosticTabs.Items[5]).Content=GroupDiagnosticText(GroupDiagnosticExport());
    }
